/// <summary>
/// PricingAttribute of table <c>InventTable</c> field PdsCWWMSMinimumPalletQty.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTablePdsCWWMSMinimumPalletQty extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, PdsCWWMSMinimumPalletQty);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Real);
    InventTable inventTable;

    while select inventTable
        group by PdsCWWMSMinimumPalletQty
    {
        if (! ret.in(inventTable.PdsCWWMSMinimumPalletQty))
        {
            ret.add(inventTable.PdsCWWMSMinimumPalletQty);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, PdsCWWMSMinimumPalletQty));
    qbr.value(queryValue(_value));
}
